{"template": "用数字 {digits_str} 组成一个 {n}-位数，要求：{condition_desc}。这个数是______。", "slots": {"digits_str": {"type": "choice", "options": ["3, 3, 3, 0, 0", "5, 5, 5, 0, 0", "8, 8, 8, 0, 0", "2, 2, 2, 0, 0"]}, "n": {"type": "int", "min": 5, "max": 5}, "condition_type": {"type": "choice", "options": ["max", "min_nonzero_start", "specific_zero_pos"]}, "condition_desc": {"type": "choice", "options": ["最大的五位数", "最小的五位数", "千位上的数字是0的最小数"]}}, "constraints": ["(condition_type == 'max' and condition_desc == '最大的五位数') or (condition_type == 'min_nonzero_start' and condition_desc == '最小的五位数') or (condition_type == 'specific_zero_pos' and condition_desc == '千位上的数字是0的最小数')"], "verifiable_type": "program", "solver": "def solve(digits_str, n, condition_type, condition_desc):
    raw_digits = [int(x.strip()) for x in digits_str.split(',')]

    def get_permutations(items):
        if len(items) == 1:
            return [items]
        res = []
        seen = set()
        for i, item in enumerate(items):
            if item in seen:
                continue
            seen.add(item)
            rest = items[:i] + items[i+1:]
            for p in get_permutations(rest):
                res.append([item] + p)
        return res

    perms = get_permutations(raw_digits)

    valid_numbers = []
    for p in perms:
        if p[0] == 0:
            continue
        num_val = int(''.join(map(str, p)))
        valid_numbers.append(num_val)

    if not valid_numbers:
        return None

    if condition_type == 'max':
        return max(valid_numbers)
    elif condition_type == 'min_nonzero_start':
        return min(valid_numbers)
    elif condition_type == 'specific_zero_pos':
        # 千位是第2位（从左往右，索引1）
        target_idx = 1 
        candidates = [num for num in valid_numbers if str(num)[target_idx] == '0']
        if candidates:
            return min(candidates) 
        else:
            return None
    return None", "answer_f

